test('uploads a small file and returns its id', async (t) => {
  // Stub fetch so the test does not need a running upload server (none exists in CI).
  const calls = [];
  t.mock.method(globalThis, 'fetch', async (url, opts) => {
    calls.push({ url, opts });
    return new Response(JSON.stringify({ id: 'abc123' }), { status: 200 });
  });

  const id = await upload('a.txt', Buffer.from('hello'));
  assert.match(id, /^[a-z0-9]+$/);
  assert.equal(calls.length, 1);
  assert.equal(calls[0].opts.method, 'POST');
  assert.match(calls[0].url, /\?name=a\.txt$/);
});

